    await page.goto("/#/");
    const cookieBtn = page.getByRole("button", { name: "Me want it!" });
    if (await cookieBtn.isVisible()) await cookieBtn.click();

    // Click the product card to open the detail dialog
    await page.locator("mat-card").filter({ hasText: "Apple Juice (1000ml)" }).getByRole("button", { name: "Click for more information about the product" }).click();

    // Wait for the product detail dialog to appear
    await expect(page.locator("mat-dialog-container")).toBeVisible();

    // Find the review text field and enter a review
    const reviewTextarea = page.locator("mat-dialog-container").locator("textarea");
    await expect(reviewTextarea, "Precondition: review textarea must be visible for signed-in user").toBeVisible();
    await reviewTextarea.fill("Great juice, highly recommended!");

    // Click Submit
    await page.locator("mat-dialog-container").getByRole("button", { name: "Submit" }).click();

    // Assert confirmation is shown
    await expect(page.getByText("Your review was submitted successfully")).toBeVisible();
  });

  // @story:SCRUM-21
  // @ac:2
  // @design:D12
  // @type:functional
  // @technique:state-transition
  test("AC-2 – The submitted review appears in the product reviews with the customer email as author", async ({ page }) => {
    const baseURL = process.env["AQA_APP_URL"] || "http://localhost:3100";

    // Precondition: sign in via API and confirm authentication succeeded
    const apiContext = await playwrightRequest.newContext({ baseURL });
    const loginResp = await apiContext.post("/rest/user/login", {
      data: { email: process.env["AQA_APP_USER"], password: process.env["AQA_APP_PASS"] },
    });
    expect(loginResp.status(), "Precondition: login must succeed (200) — check AQA_APP_USER / AQA_APP_PASS").toBe(200);
    const loginBody = await loginResp.json();
    const token = loginBody?.authentication?.token;
    expect(token, "Precondition: authentication token must be present in login response").toBeTruthy();
    const userEmail = process.env["AQA_APP_USER"];
    await apiContext.dispose();

    // Authenticate the browser session
    await page.goto("/#/");
    await page.evaluate((t) => { localStorage.setItem("token", t); }, token);

    // Navigate to product list
    await page.goto("/#/");
    const cookieBtn = page.getByRole("button", { name: "Me want it!" });
    if (await cookieBtn.isVisible()) await cookieBtn.click();

    // Open Apple Juice (1000ml) detail
    await page.locator("mat-card").filter({ hasText: "Apple Juice (1000ml)" }).getByRole("button", { name: "Click for more information about the product" }).click();
    await expect(page.locator("mat-dialog-container")).toBeVisible();

    // Enter and submit review
    const reviewTextarea = page.locator("mat-dialog-container").locator("textarea");
    await expect(reviewTextarea, "Precondition: review textarea must be visible for signed-in user").toBeVisible();
    await reviewTextarea.fill("Great juice, highly recommended!");
    await page.locator("mat-dialog-container").getByRole("button", { name: "Submit" }).click();

    // Confirm submission succeeded
    await expect(page.getByText("Your review was submitted successfully")).toBeVisible();

    // The submitted review text appears in the product reviews
    await expect(page.locator("mat-dialog-container").getByText("Great juice, highly recommended!")).toBeVisible();

    // The review shows the customer's email as author
    await expect(page.locator("mat-dialog-container").getByText(userEmail!)).toBeVisible();
  });

  // @story:SCRUM-21
  // @ac:3
  // @design:D13
  // @type:functional
  // @technique:boundary-value-analysis
  test("AC-3 – The submit button is disabled while the review text is empty", async ({ page }) => {
    const baseURL = process.env["AQA_APP_URL"] || "http://localhost:3100";

    // Precondition: sign in via API and confirm authentication succeeded
    const apiContext = await playwrightRequest.newContext({ baseURL });
