    });
    expect(loginResp.status(), "Precondition: login must succeed (200) — check AQA_APP_USER / AQA_APP_PASS").toBe(200);
    const loginBody = await loginResp.json();
    const token = loginBody?.authentication?.token;
    expect(token, "Precondition: authentication token must be present in login response").toBeTruthy();
    await apiContext.dispose();

    // Authenticate the browser session
    await page.goto("/#/");
    await page.evaluate((t) => { localStorage.setItem("token", t); }, token);

    // Navigate to product list
    await page.goto("/#/");
    const cookieBtn = page.getByRole("button", { name: "Me want it!" });
    if (await cookieBtn.isVisible()) await cookieBtn.click();

    // Open Apple Juice (1000ml) detail
    await page.locator("mat-card").filter({ hasText: "Apple Juice (1000ml)" }).getByRole("button", { name: "Click for more information about the product" }).click();
    await expect(page.locator("mat-dialog-container")).toBeVisible();

    // The review textarea should be visible (signed-in user)
    const reviewTextarea = page.locator("mat-dialog-container").locator("textarea");
    await expect(reviewTextarea, "Precondition: review textarea must be visible for signed-in user").toBeVisible();

    // Assert Submit button is disabled when textarea is empty
    const submitBtn = page.locator("mat-dialog-container").getByRole("button", { name: "Submit" });
    await expect(submitBtn).toBeDisabled();
  });

  // @story:SCRUM-21
  // @ac:1
  // @design:D14
  // @type:security
  // @technique:equivalence-partitioning
  test("AC-1 – An unauthenticated user cannot write a review", async ({ page }) => {
    // Navigate as guest (no authentication)
    await page.goto("/#/");
    const cookieBtn = page.getByRole("button", { name: "Me want it!" });
    if (await cookieBtn.isVisible()) await cookieBtn.click();

