  // ---------------------------------------------------------------------------
  // SCRUM-21 – Customer writes a review of a product
  // ---------------------------------------------------------------------------

  // Helper: sign in via API and inject token into browser session
  async function signInAndInjectToken(page: any, apiContext: any): Promise<{ token: string; email: string }> {
    const email = process.env["AQA_APP_USER"] as string;
    const password = process.env["AQA_APP_PASS"] as string;
    const loginResp = await apiContext.post("/rest/user/login", {
      data: { email, password },
    });
    expect(loginResp.status(), "Precondition: login must succeed (200) — check AQA_APP_USER / AQA_APP_PASS").toBe(200);
    const loginBody = await loginResp.json();
    const token = loginBody?.authentication?.token as string;
    expect(token, "Precondition: authentication token must be present in login response").toBeTruthy();
    await page.goto("/#/");
    await page.evaluate((t: string) => { localStorage.setItem("token", t); }, token);
    return { token, email };
  }

